<?php
namespace App\Http\Controllers\Admin; use App\Http\Controllers\Controller; use App\Models\MediaAsset; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class MediaManagerController extends Controller { public function index(){return view('admin.media',['assets'=>MediaAsset::latest()->paginate(40)]);} public function store(Request $r){$d=$r->validate(['file'=>'required|file|max:10240|mimes:jpg,jpeg,png,webp,gif,svg,mp4,webm','alt_text'=>'nullable|string|max:180','credit'=>'nullable|string|max:180','license'=>'nullable|string|max:120']);$f=$r->file('file');$path=$f->store('media/'.now()->format('Y/m'),'public');MediaAsset::create(['uploaded_by'=>$r->user()->id,'disk'=>'public','path'=>$path,'mime_type'=>$f->getMimeType(),'size'=>$f->getSize(),'alt_text'=>$d['alt_text']??null,'credit'=>$d['credit']??null,'license'=>$d['license']??null]);return back()->with('status','Media uploaded');} public function destroy(MediaAsset $mediaAsset){Storage::disk($mediaAsset->disk)->delete($mediaAsset->path);$mediaAsset->delete();return back()->with('status','Media deleted');} }
